function render(){stop();root.style.setProperty('--nf-sheet',(['production','references','compare'].includes(state.view)||(state.view==='phase'&&state.inspectPhase==='References'))?'var(--nf-prod-sheet)':'var(--nf-sketch-sheet)');root.style.setProperty('--nf-accent',state.pack==='Music Video'?'#D940A0':'#a9bdcf');root.style.setProperty('--nf-columns',state.columns);$('.pack').textContent=state.pack==='Music Video'?'Music Video · active':'Core workflow';$('[data-action="workflow"]').textContent=(state.phase==='Shot preparation'?'Shot planning':state.phase)+' '+ '⌄';$$('[data-work]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.work===state.work)));let content='';if(state.view==='budget')content=heading('Production budget','Recorded example','<button data-action="board">Close</button>')+'<div class="reading"><dl class="facts"><dt>Limit</dt><dd>€50.00</dd><dt>Spent</dt><dd>€0.26</dd><dt>Reserved</dt><dd>€0.00</dd><dt>Available</dt><dd>€49.74</dd></dl><p class="muted">Production cost is presented with the exact job package before approval.</p></div>';else if(state.view==='workflow')content=workflow();else if(state.view==='sources')content=sources();else if(state.work==='generate')content=generation();else if(state.work==='edit')content=edit();else if(state.view==='reopen')content=heading('Reopen Shot preparation?','Explicit revision','<button data-action="board">Cancel</button>')+'<div class="reading"><p>Shot preparation and all later approvals are reset. Existing artifacts remain available. No new job starts.</p><button class="primary" data-action="confirm-reopen">Reopen Shot preparation</button></div>';else content=({board,detail,list,animatic:player,review,references,phase:phaseView,blocking,production:productionImages,compare:compareImages}[state.view]||board)();$('main').innerHTML=content;
let action='',status='Shot preparation · draft v'+state.revision;
if(state.running){status=['Checking references','Checking timing','Reviewing the sequence'][state.stage]+' · simulated';action='<button data-action="stop">Stop review</button>';}else if(state.approved){status='Shot preparation approved · next: Sanity Check';action='<button class="secondary" data-action="next">Open next step</button>';}else if(state.resolved){status='Review complete · your decision';action='<button class="primary" data-action="approve">Approve Shot preparation</button>';}else if(state.review==='finding'){status='Review · one creative decision';action='<button class="primary" data-action="review">Review cut 1C → 1D</button>';}else action='<button class="primary" data-action="check">Review shot plan</button>';
$('footer').innerHTML='<button class="small" data-action="budget">€49.74 available</button><span class="grow"></span><span class="small muted" role="status">'+status+'</span>'+action;desktopChrome();spatialInspector();drawBlocking();paint();if(globalThis.lucide)lucide.createIcons();}
function changed(){invalidate(state.phase);state.revision++;state.review='pending';state.resolved=false;state.frame=0;go('board');}
function runReview(){if(state.running||state.approved)return;state.running=true;state.stage=0;go('board');const advance=()=>{state.stage++;if(state.stage===3){state.running=false;state.review='finding';go('review');}else{render();timer=setTimeout(advance,650);}};timer=setTimeout(advance,650);}
root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.work){state.work=b.dataset.work;go('board');return;}if(b.hasAttribute('data-shot')){state.selected=+b.dataset.shot;state.inspector=true;go(state.view==='production'?'production':'detail');return;}if(b.hasAttribute('data-seek')){stop();state.frame=+b.dataset.seek;paint();return;}if(b.dataset.phase){state.inspectPhase=b.dataset.phase;state.work='plan';go(b.dataset.phase==='Shot preparation'?'board':'phase');return;}const a=b.dataset.action;if(!a)return;
if(['board','detail','list','animatic','review','workflow','sources','references','budget','reopen','blocking','production','compare'].includes(a)){go(a);return;}
if(a==='save'){const x=Number($('#nf-duration').value);if(!Number.isFinite(x)||x<.5||x>30||x*2%1){$('.error').textContent='Use 0.5–30 seconds in 0.5-second steps.';return;}if(state.running||state.approved)return;shots[state.selected].duration=x;changed();}
if(a==='play'){if(playing){stop();paint();}else{if(state.frame>=total()-1)state.frame=0;playing=true;origin=state.frame;startTime=performance.now();paint();raf=requestAnimationFrame(tick);}}
if(a==='current'){state.selected=(rows().find(s=>state.frame<s.end)||rows().at(-1)).index;go('detail');}
if(a==='cut'){state.frame=rows()[2].start;go('animatic');}
if(a==='check')runReview();
if(a==='stop'){clearTimeout(timer);state.running=false;state.review='pending';render();}
if(a==='hold'&&!state.running&&!state.approved&&shots[2].duration<30){shots[2].duration++;changed();}
if(a==='keep'){state.resolved=true;go('board');}
if(a==='approve'&&state.resolved&&!state.running){state.approved=true;state.phase='Sanity Check';go('board');}
if(a==='next'||a==='resume'){state.inspectPhase=state.phase;state.work='plan';go(state.phase==='Shot preparation'?'board':'phase');}
if(a==='confirm-reopen'){state.approved=false;state.resolved=false;state.review='pending';state.phase='Shot preparation';go('board');}
if(a==='import'){state.sourcePreview=true;render();}
});
