const demo={scenario:'Preparation',intake:0,lyrics:'',track:false,analysis:false,material:0,phaseDraft:false,phaseReview:false,phaseText:{},reopenTarget:'',asset:'generated',entity:1,packageReady:false,job:'idle',jobStep:0,completed:0,stale:false,fail:false,takes:false,takeAccepted:false,delivery:false,notice:'',history:[],frameApproved:false};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const xb=(id,label,disabled=false,primary=false)=>'<button data-x="'+id+'" '+(disabled?'disabled':'')+' class="'+(primary?'primary':'secondary')+'">'+label+'</button>';
const group=(title,body,open=true)=>'<details class="ins-group" '+(open?'open':'')+'><summary>'+title+'</summary><div>'+body+'</div></details>';
const originals={render,phaseView,referencesNew,sources,generation,edit};
let jobTimer=0;
function setScenario(name){clearTimeout(timer);clearTimeout(jobTimer);stop();Object.assign(state,{work:'plan',view:'board',phase:'Shot preparation',approved:false,resolved:false,review:'pending',running:false,revision:1,selected:2,frame:0,inspector:true});Object.assign(demo,{scenario:name,phaseText:{},intake:0,track:false,analysis:false,material:0,phaseDraft:false,phaseReview:false,packageReady:false,job:'idle',jobStep:0,completed:0,stale:false,fail:false,takes:false,takeAccepted:false,delivery:false,frameApproved:false,notice:'',history:[]});[3,2,4,3,5,3].forEach((d,i)=>{Object.assign(shots[i],originalShots[i]);shots[i].duration=d;shots[i].useRendering=false;shots[i].scale=100;shots[i].frameMode='start';});if(name==='New project'){state.phase='Project Init';state.view='intake';}if(name==='Ready to generate'){state.phase='Render';state.approved=true;demo.packageReady=true;demo.frameApproved=true;state.work='generate';}if(name==='Media review'){state.view='media';}if(name==='Mixed frame requirements'){shots[5].frameMode='references';state.phase='Frames';state.inspectPhase='Frames';state.view='phase';state.approved=true;}seedContract();render();}
function testCases(){return heading('Test scenarios','Clickdummy · local example data · no provider calls')+'<div class="reading">'+['Preparation','New project','Ready to generate','Media review','Mixed frame requirements'].map(n=>'<div class="case-row"><div><h3>'+n+'</h3><p class="small muted">'+({'Preparation':'Select shots, edit timing, play the animatic, inspect blocking and approve a review.','New project':'Track → optional lyrics → initialization → analysis approval → optional creative material.','Ready to generate':'Approve an example cost ceiling, cancel or fail a job, retry and review the result.','Mixed frame requirements':'Five start-frame shots and one reference-driven shot; no universal first-frame requirement.','Media review':'Inspect imported, generated, AI-edited and unavailable assets.'}[n])+'</p></div><button data-scenario="'+n+'">Load scenario</button></div>').join('')+'<div class="case-row"><label>Example workflow<select data-example-pack><option '+(state.pack==='Music Video'?'selected':'')+'>Music Video</option><option '+(state.pack==='Generic'?'selected':'')+'>Generic</option></select></label><span class="small muted">Loads a different example project. Never changes a real project’s pinned pack.</span></div><div class="case-row"><label><input type="checkbox" data-fail '+(demo.fail?'checked':'')+'> Simulate next job failing</label></div>'+xb('return','Return to project')+'</div>';}
function intakeView(){const music=state.pack==='Music Video';const steps=music?['Track','Lyrics','Project Init','Audio Analysis','Existing story','Prepared characters','Prepared locations','Style references']:['Project Init','Existing story','Prepared characters','Prepared locations','Style references'];const step=steps[demo.intake]||'Brief';let body='';if(step==='Track')body='<h2>Assign the project track</h2><p class="muted">Available in Media · not assigned</p><label class="choice-row"><input type="radio" name="track" data-track '+(demo.track?'checked':'')+'> Claude Mouse.wav <span class="muted">20 s · example excerpt</span></label>'+xb('intake-next','Assign track',!demo.track,true);else if(step==='Lyrics')body='<h2>Add lyrics</h2><label class="field">Lyrics<textarea data-lyrics rows="6" placeholder="Paste the song lyrics">'+esc(demo.lyrics)+'</textarea></label><div class="row">'+xb('intake-next','Continue without lyrics')+xb('lyrics-save','Use lyrics',!demo.lyrics.trim(),true)+'</div>';else if(step==='Project Init')body='<h2>'+ (music?'Track assigned. Ready to initialize.':'Start a new film.')+'</h2><p class="muted">'+(music?'The next step analyzes the assigned audio.':'Develop a brief from your direction or existing material.')+'</p>'+xb('intake-next','Initialize project',false,true);else if(step==='Audio Analysis')body='<h2>Track structure</h2><div class="analysis-strip"><span>Intro · 0–5 s</span><span>Confrontation · 5–12 s</span><span>Resolution · 12–20 s</span></div><p class="muted">Illustrative analysis of this excerpt. Review the section boundaries before developing the story.</p>'+xb('analysis-review','Review analysis',demo.analysis)+xb('intake-next','Approve analysis',!demo.analysis,true);else body='<h2>'+step+' · optional</h2><p class="muted">Use existing material, or continue from scratch.</p><div class="row">'+xb('material-example','Use example '+step.toLowerCase())+xb('filmflow','Preview FilmFlow import')+'</div><p class="small muted">'+(demo.material?'Example material selected.':'No material assigned.')+'</p><div class="row">'+xb('intake-next','Skip')+xb('intake-next','Use selected material',!demo.material,true)+'</div>';return heading(step,'Project setup · '+(demo.intake+1)+' / '+steps.length)+'<div class="reading">'+body+'</div>';}
function phaseDocument(){const p=state.inspectPhase;if(p==='References')return referencesNew();if(p==='Storyboard')return board();if(p==='Shot preparation')return board();if(p==='Sanity Check')return heading('Production checks','Shot plan v'+state.revision)+'<div class="reading"><h2>Check the approved production plan</h2><ul class="check-list"><li>Shot identities and durations</li><li>Reference roles and source bindings</li><li>Camera setups, axis and blockout</li><li>Execution route and required frame slots</li></ul><p class="muted">'+(demo.phaseReview?'Example checks complete. No structural blockers.':'Run the review before approving this step.')+'</p>'+xb('phase-check','Run checks',state.phase!==p||demo.phaseReview,true)+xb('sanity-approve','Approve checks',state.phase!==p||!demo.phaseReview,true)+'</div>';if(p==='Frames')return heading('Production frames','Approved execution routes determine required image slots')+'<div class="grid">'+shots.slice(0,3).map((s,i)=>'<article>'+art(i).replace('class="image"','class="image production-image"')+'<h3>'+s.id+' · Start frame</h3><p class="small muted">Example route: generated clip with a start frame</p></article>').join('')+'</div><div class="row">'+xb('frames-approve','Approve example frames',state.phase!=='Frames',true)+'</div>';if(p==='Render')return heading('Render','Video jobs are prepared in Generate')+'<div class="reading">'+xb('open-generate','Open Generate',false,true)+'</div>';const text=demo.phaseText[p]||({'Project Init':'Claude Mouse · Music Video · 20-second excerpt. Track assigned, optional lyrics declined.','Audio Analysis':'0–5 s: establish the empty street. 5–12 s: conflict and decision. 12–20 s: transformation and return.','Brief':'A small mouse turns the cat’s tools of control into comforts for the whole town. Preserve the mouse’s agency and make every change visible.','Production Design':'A miniature frontier town. Warm ochre daylight, worn brass machinery and soft fur. Keep the street axis consistent. The Comfort Engine remains in the street.','Treatment':'The empty street belongs to the cat. A mouse arrives with a brass cog. The cat blocks the porch. The mouse changes course and repairs the street mechanism. Power returns as comfort. The town joins the mouse; the cat’s authority dissolves.'}[p]||'No artifact is available.');const current=state.phase===p;return heading(p,current?'Current phase · '+(demo.phaseDraft?'draft':'ready to work'):'Approved artifact · read only')+'<div class="reading"><h2>'+({'Treatment':'From control to comfort',Brief:'The town belongs to everyone','Production Design':'A single street, transformed'}[p]||p)+'</h2>'+(current&&demo.phaseDraft?'<label class="field">Creative direction<textarea rows="10" data-phase-text>'+esc(text)+'</textarea></label><div class="row">'+xb('doc-save','Save direction',false,true)+xb('doc-reset','Reset draft')+'</div>':'<p class="document-prose">'+esc(text)+'</p>')+'<div class="row">'+(current?xb('doc-edit','Edit direction')+xb('phase-check','Review artifact',demo.phaseReview||demo.phaseDraft)+xb('doc-approve','Approve '+p,!demo.phaseReview||demo.phaseDraft,true):'<button data-reopen-phase="'+p+'">Reopen '+p+'</button>')+'</div>'+(demo.phaseReview&&current?'<p class="small success">Review complete · example structural and creative checks</p>':'')+'</div>';}
function mediaView(){const labels={imported:'Street-blockout.mov',generated:'Claude-Mouse-reference.png',edited:'Claude-Mouse-reference-v2.png',unavailable:'Porch-panorama.png'};return heading('Media','Library assets · assignment remains explicit')+'<div class="refs-tabs">'+Object.keys(labels).map(k=>'<button data-asset="'+k+'" aria-pressed="'+(demo.asset===k)+'">'+({imported:'Imported',generated:'Generated',edited:'AI-edited',unavailable:'Unavailable'}[k])+'</button>').join('')+'</div><div class="reading">'+(demo.asset==='unavailable'?'<div class="import-well">Source file unavailable</div>':art(demo.asset==='imported'?0:1).replace('class="image"','class="image production-image"'))+'<h2>'+labels[demo.asset]+'</h2><p class="muted">'+(demo.asset==='imported'?'Imported blocking footage · example poster frame':demo.asset==='unavailable'?'Relink the original source before using this asset.':'Rendered reference · illustrative asset')+'</p></div>';}
function assetInspector(){const kind=demo.asset;return '<div class="inspector-heading">MEDIA INSPECTOR</div><h2>'+({imported:'Street-blockout.mov',generated:'Claude-Mouse-reference.png',edited:'Claude-Mouse-reference-v2.png',unavailable:'Porch-panorama.png'}[kind])+'</h2>'+group('AI actions',xb('asset-action','Prepare image variation',kind==='imported'||kind==='unavailable')+'<p class="small muted">'+(kind==='unavailable'?'Source unavailable.':kind==='imported'?'No image action for a video source.':'Opens a scoped proposal. No generation starts.')+'</p>')+group('Provenance','<dl class="facts"><dt>Origin</dt><dd>'+kind+'</dd><dt>Provider</dt><dd>'+(kind==='imported'?'Not applicable':'Unknown · example asset')+'</dd><dt>Model</dt><dd>'+(kind==='imported'?'Not applicable':'Not recorded')+'</dd><dt>Cost</dt><dd>Not recorded</dd><dt>Parent</dt><dd>'+(kind==='edited'?'Claude-Mouse-reference.png':'None')+'</dd><dt>Role</dt><dd>Not assigned</dd></dl>')+group('File information','<dl class="facts"><dt>Availability</dt><dd>'+(kind==='unavailable'?'Missing':'Example only')+'</dd><dt>Location</dt><dd>Project media</dd></dl>',false);}
function filmflowView(){return heading('Import from FilmFlow','Optional · example import preview')+'<div class="reading"><h2>Claude Mouse · Version 3</h2><table class="import-table"><thead><tr><th>FilmFlow</th><th>NexGenVideo</th></tr></thead><tbody><tr><td>Scene / shot labels</td><td>Scene / shot links</td></tr><tr><td>Duration and camera notes</td><td>Shot draft and animatic timing</td></tr><tr><td>Storyboard images</td><td>Sketches</td></tr><tr><td>Characters / props / locations</td><td>References with source attribution</td></tr></tbody></table><p class="muted">6 shots · 6 sketches · 3 entity references. Review the source version before copying.</p><label class="choice-row"><input type="checkbox" data-import-confirm> Use this example as imported source material</label>'+xb('import-example','Copy example material',true,true)+'<p class="small muted">Simulation only. The current MCP contract still needs stable public object identities and a consistent import snapshot. No live connection or write-back.</p>'+xb('return','Cancel')+'</div>';}
function generationView(){const ready=demo.packageReady;return heading('Generate','Prepared shot packages · one controlled execution')+'<div class="reading">'+(!ready?'<h2>Preparation is not yet approved</h2><ul class="check-list"><li>Shot preparation '+(state.approved?'approved':'awaiting approval')+'</li><li>Production checks '+(state.phase==='Frames'?'approved':'pending')+'</li><li>Required production frames '+(demo.frameApproved?'approved':'pending')+'</li></ul>'+xb('current-phase','Open current step',false,true):'<h2>Scene 1 · 6 prepared shots</h2><dl class="facts"><dt>Input</dt><dd>Approved shot plan v'+state.revision+'</dd><dt>References</dt><dd>'+requiredFrames().length+' example start frames · '+(6-requiredFrames().length)+' reference-driven shots</dd><dt>Route</dt><dd>Simulated video adapter</dd><dt>Maximum cost</dt><dd>€3.60 · example ceiling</dd><dt>Available</dt><dd>€49.74</dd></dl><p class="muted">'+({idle:'Review the package before authorizing it.',running:'Running example job · '+demo.jobStep+' / 6 shots',failed:'Example provider failure. Completed output remains available; retry applies to the remaining items.',canceled:'Stopped. Finished items are retained.',complete:'6 example take records ready for review.'}[demo.job])+'</p><div class="row">'+(demo.job==='running'?xb('job-cancel','Cancel job'):demo.job==='complete'?xb('take-review','Review takes',false,true):xb('job-confirm',demo.job==='idle'?'Review and authorize':'Review remaining jobs',false,true))+'</div>')+'</div>';}
function packageView(){return heading('Authorize generation','Example package · no paid request')+'<div class="reading"><h2>'+ (6-demo.completed)+' remaining shots · maximum €'+((6-demo.completed)*.6).toFixed(2)+'</h2><p class="document-prose">This approval applies only to the displayed plan revision, input references and example route. A changed package needs a new approval.</p><label class="choice-row"><input type="checkbox" data-spend-confirm> Approve the €'+((6-demo.completed)*.6).toFixed(2)+' example ceiling</label>'+xb('job-start','Start simulated generation',true,true)+xb('open-generate','Cancel')+'</div>';}
