function editView(){return heading('Edit','One timeline · shot and reference links retained')+'<div class="reading">'+(demo.takeAccepted?art(state.selected).replace('class="image"','class="image production-image"'):'<div class="import-well">No accepted takes on the timeline</div>')+'<div class="row"><span class="mono">'+code(rows()[state.selected].start)+' / '+code(total())+'</span><span class="grow"></span><span class="small muted">'+(demo.takeAccepted?'Example cut · poster preview':'Planning placeholders')+'</span></div><div class="timeline">'+shots.map((s,i)=>'<button data-clip="'+i+'" style="flex:'+s.duration+'" '+(!demo.takeAccepted?'disabled':'')+'>'+s.id+'<br>'+s.duration+' s</button>').join('')+'</div><p class="small muted">'+(demo.takeAccepted?'Select a clip to inspect its values and source shot. Playback of real video and native trimming remain app functions.':'Approve a sequence in Generate to simulate its handoff to Edit.')+'</p>'+xb('source-shot','Inspect source shot')+'</div>';}
function finishView(){return heading('Finish','Sequence review and delivery')+'<div class="reading"><h2>'+ (demo.delivery?'Example delivery recorded':'Prepare the final delivery')+'</h2><dl class="facts"><dt>Sequence</dt><dd>'+(demo.stale?'Source changed · review required':demo.takeAccepted?'Accepted example cut':'No accepted cut')+'</dd><dt>Duration</dt><dd>'+code(total())+'</dd><dt>Output</dt><dd>H.264 · 1920 × 1080 · 24 fps</dd></dl><p class="small muted">Delivery is simulated. No media file is exported.</p>'+xb('delivery','Simulate delivery',!demo.takeAccepted||demo.delivery||demo.stale,true)+'</div>';}
function customInspector(){if(state.view==='media')return assetInspector();if(state.view==='references'||(state.view==='phase'&&state.inspectPhase==='References'))return '<div class="inspector-heading">REFERENCE</div><h2>'+ (demo.entity===1?'Claude Mouse':'AI Cat')+'</h2>'+group('Identity','<p class="small">'+(demo.entity===1?'Small grey mouse · brown workwear · brass cog':'Dark cat · sheriff badge · porch silhouette')+'</p>')+group('Used in shots','<div class="row">'+[1,2,5].map(i=>'<button data-source-shot="'+i+'">'+shots[i].id+'</button>').join('')+'</div>')+group('Image provenance','<p class="small muted">Rendered example · provider and model not recorded. Identity reference; not a storyboard sketch.</p>');if(state.work==='edit'&&demo.takeAccepted)return '<div class="inspector-heading">CLIP / '+shots[state.selected].id+'</div>'+group('Transform','<label class="field">Scale · %<input type="number" data-scale value="'+(shots[state.selected].scale||100)+'" min="10" max="400"></label>'+xb('scale-save','Apply scale')+((shots[state.selected].scale||100)!==100?xb('scale-reset','Reset transform'):'')+'<p class="error" role="alert"></p>')+group('Source','<p>'+shots[state.selected].id+' · Take 1</p>'+xb('source-shot','Inspect source shot'))+group('File information','<p class="small muted">Example take record · no local video</p>',false);return null;}
referencesNew=function(){return originals.referencesNew().replace(/<article>/g,'<article class="reference-card">').replace(/<h3 style="margin-top:10px">Claude Mouse<\/h3>/,'<button data-entity="1">Inspect Claude Mouse</button>').replace(/<h3 style="margin-top:10px">AI Cat<\/h3>/,'<button data-entity="2">Inspect AI Cat</button>');};
phaseView=phaseDocument;sources=filmflowView;generation=generationView;edit=editView;
render=function(){originals.render();if(state.view==='intake')$('main').innerHTML=intakeView();if(state.view==='scenarios')$('main').innerHTML=testCases();if(state.view==='media')$('main').innerHTML=mediaView();if(state.view==='filmflow')$('main').innerHTML=filmflowView();if(state.view==='package')$('main').innerHTML=packageView();if(state.view==='takes')$('main').innerHTML=takeView();if(state.work==='finish'&&state.view==='board')$('main').innerHTML=finishView();if(state.view==='phase-reopen')$('main').innerHTML=heading('Reopen '+demo.reopenTarget+'?','Existing artifacts remain available')+'<div class="reading"><p class="document-prose">This makes '+demo.reopenTarget+' the current phase and invalidates its approval and every later approval. Generated media is retained; its source binding must be checked again.</p>'+xb('reopen-confirm','Reopen and invalidate approvals',state.running||demo.job==='running',true)+xb('return','Cancel')+'</div>';if(state.view==='asset-action')$('main').innerHTML=heading('Prepare a variation','Claude-Mouse-reference.png · scoped direction')+'<div class="reading"><label class="field">Change requested<textarea rows="4" placeholder="Describe the desired visual change"></textarea></label><p class="muted">Provider and model provenance are unavailable for this example. Select an executable route in the native app before preparing a request.</p><button disabled>Prepare request</button>'+xb('media','Back to asset')+'</div>';if(state.view==='repair')$('main').innerHTML=heading('Repair shot '+shots[state.selected].id,'Selected take · preserve approved identity and blocking')+'<div class="reading"><label class="field">Reason<select><option>Continuity</option><option>Composition</option><option>Technical</option></select></label><label class="field">Required correction<textarea rows="4" data-repair placeholder="Describe the correction"></textarea></label>'+xb('repair-save','Save repair request',false,true)+xb('take-review','Cancel')+'</div>';const ins=customInspector();if(ins)$('.context-inspector').innerHTML=ins;$$('.context-inspector .section').forEach(el=>{const h=el.querySelector('h3');if(h){const d=document.createElement('details');d.className='ins-group';d.open=true;d.innerHTML='<summary>'+h.textContent+'</summary>';h.remove();const body=document.createElement('div');body.append(...el.childNodes);d.append(body);el.replaceWith(d);}});if(state.view==='intake'||state.view==='scenarios'||state.view==='phase-reopen')$('.context-inspector').innerHTML='<div class="inspector-heading">PROJECT</div><h2>Claude Mouse</h2><p class="small muted">'+state.pack+' · local example</p>';if(!['board','list','animatic','review','reopen','blocking','production','compare'].includes(state.view)||state.work!=='plan')$('footer').innerHTML='<button data-action="budget">€49.74 available</button><span class="grow"></span><span class="small muted">'+esc(demo.notice||('Current phase · '+state.phase))+'</span>';if(!$('.demo-controls')){const bar=document.createElement('div');bar.className='demo-controls';bar.innerHTML='<span>CLICKDUMMY · simulated project</span><span class="grow"></span>'+xb('scenarios','Test scenarios')+xb('media','Media');root.append(bar);}if(globalThis.lucide)lucide.createIcons();};
function log(message){demo.notice=message;demo.history.push(message);}
function startJob(){demo.job='running';demo.jobStep=demo.completed;state.work='generate';state.view='board';log('Generation authorized · example ceiling €3.60');render();const step=()=>{if(demo.job!=='running')return;demo.jobStep++;if(demo.fail&&demo.jobStep===2){demo.job='failed';demo.fail=false;log('Example provider failure · retry available');render();return;}demo.completed=demo.jobStep;if(demo.jobStep===6){demo.job='complete';demo.takes=true;contract.takeBinding=contract.jobBinding;log('6 example take records ready');render();return;}render();jobTimer=setTimeout(step,450);};jobTimer=setTimeout(step,450);}
root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const special=b.dataset.x||b.dataset.scenario||b.dataset.asset||b.dataset.reopenPhase||b.dataset.entity||b.dataset.clip||b.dataset.take||b.dataset.sourceShot;const hasSpecial=b.hasAttribute('data-clip')||b.hasAttribute('data-take')||b.hasAttribute('data-source-shot');if(!special&&!hasSpecial)return;e.stopImmediatePropagation();const x=b.dataset.x;if(b.dataset.scenario){setScenario(b.dataset.scenario);return;}if(b.dataset.asset){demo.asset=b.dataset.asset;go('media');return;}if(b.dataset.entity){demo.entity=+b.dataset.entity;render();return;}if(b.hasAttribute('data-clip')||b.hasAttribute('data-take')){state.selected=+(b.dataset.clip??b.dataset.take);render();return;}if(b.hasAttribute('data-source-shot')){state.selected=+b.dataset.sourceShot;state.work='plan';go('board');return;}if(b.dataset.reopenPhase){demo.reopenTarget=b.dataset.reopenPhase;go('phase-reopen');return;}if(['scenarios','media','filmflow','asset-action','repair'].includes(x)){state.work='plan';go(x);return;}if(x==='return'){state.work='plan';go(demo.scenario==='New project'&&state.phase==='Project Init'?'intake':'board');}if(x==='intake-next'||x==='lyrics-save'){demo.intake++;demo.material=0;const end=state.pack==='Music Video'?8:5;if(demo.intake>=end){state.phase='Brief';state.inspectPhase='Brief';demo.phaseDraft=true;demo.phaseReview=false;go('phase');}else go('intake');}if(x==='analysis-review'){demo.analysis=true;render();}if(x==='material-example'){demo.material=1;render();}if(x==='import-example'){demo.material=1;log('FilmFlow example copied as source material');go(demo.scenario==='New project'?'intake':'board');}if(x==='doc-edit'){demo.phaseDraft=true;render();}if(x==='doc-save'){const value=$('[data-phase-text]').value.trim();if(!value){$('[data-phase-text]').setCustomValidity('Enter creative direction.');$('[data-phase-text]').reportValidity();return;}demo.phaseText[state.inspectPhase]=value;demo.phaseDraft=false;demo.phaseReview=false;log('Direction saved · review required');render();}if(x==='doc-reset'){demo.phaseDraft=false;render();}if(x==='phase-check'){demo.phaseReview=true;log('Example review complete');render();}if(x==='doc-approve'&&demo.phaseReview){let next=phases()[phases().indexOf(state.phase)+1];state.phase=next;state.inspectPhase=next;demo.phaseReview=false;demo.phaseDraft=false;log('Approved previous artifact');go(next==='Shot preparation'?'board':'phase');}if(x==='reopen-confirm'){state.phase=demo.reopenTarget;state.inspectPhase=demo.reopenTarget;state.approved=false;state.resolved=false;demo.phaseReview=false;demo.phaseDraft=true;demo.packageReady=false;demo.frameApproved=false;demo.delivery=false;demo.stale=demo.takeAccepted;log('Downstream approvals invalidated');go('phase');}if(x==='sanity-approve'&&demo.phaseReview){state.phase='Frames';state.inspectPhase='Frames';demo.phaseReview=false;go('phase');}if(x==='frames-approve'){demo.frameApproved=true;demo.packageReady=true;state.phase='Render';state.work='generate';go('board');}if(x==='open-generate'){state.work='generate';go('board');}if(x==='current-phase'){state.work='plan';state.inspectPhase=state.phase;go(state.phase==='Shot preparation'?'board':'phase');}if(x==='job-confirm')go('package');if(x==='job-start')startJob();if(x==='job-cancel'){clearTimeout(jobTimer);demo.job='canceled';log('Job canceled · completed items retained');render();}if(x==='take-review')go('takes');if(x==='take-accept'){demo.takeAccepted=true;demo.stale=false;state.work='edit';log('Example sequence handed to Edit');go('board');}if(x==='take-repair'){state.work='plan';go('repair');}if(x==='repair-save'){if(!$('[data-repair]').value.trim()){$('[data-repair]').setCustomValidity('Describe the correction.');$('[data-repair]').reportValidity();return;}log('Scoped repair request saved · not submitted');state.work='generate';go('takes');}if(x==='source-shot'){state.work='plan';go('board');}if(x==='scale-save'){const n=Number($('[data-scale]').value);if(!Number.isFinite(n)||n<10||n>400){$('.error').textContent='Use 10–400%.';return;}shots[state.selected].scale=n;render();}if(x==='scale-reset'){shots[state.selected].scale=100;render();}if(x==='delivery'){demo.delivery=true;log('Example delivery recorded · no file exported');render();}},true);
root.addEventListener('input',e=>{if(e.target.hasAttribute('data-lyrics')){demo.lyrics=e.target.value;$('[data-x="lyrics-save"]').disabled=!demo.lyrics.trim();}if(e.target.hasAttribute('data-track')){demo.track=true;$('[data-x="intake-next"]').disabled=false;}if(e.target.hasAttribute('data-import-confirm'))$('[data-x="import-example"]').disabled=!e.target.checked;if(e.target.hasAttribute('data-spend-confirm'))$('[data-x="job-start"]').disabled=!e.target.checked;});
