const enhancedRender=render;
render=function(){enhancedRender();const mayEdit=state.work==='plan'&&['Storyboard','Shot preparation'].includes(state.phase)&&!state.approved&&!state.running;const duration=$('#nf-duration');if(duration)duration.disabled=!mayEdit;const save=$('[data-action="save"]');if(save)save.disabled=!mayEdit;if(['Storyboard','References'].includes(state.phase)&&state.work==='plan'&&((state.view==='phase'&&state.inspectPhase===state.phase)||state.view==='board'||state.view==='references'))$('footer').innerHTML='<button data-action="budget">€49.74 available</button><span class="grow"></span><span class="small muted">'+state.phase+' · '+(demo.phaseReview?'review complete':'draft')+'</span>'+xb('phase-check','Review '+state.phase,demo.phaseReview)+xb('doc-approve','Approve '+state.phase,!demo.phaseReview,true);if(demo.notice&&!$('.demo-notice')){const n=document.createElement('span');n.className='demo-notice';n.setAttribute('role','status');n.textContent=demo.notice;$('.demo-controls').prepend(n);}};
root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const a=b.dataset.action;if((a==='save'&&!['Storyboard','Shot preparation'].includes(state.phase))||(['check','approve','keep','hold'].includes(a)&&state.phase!=='Shot preparation')){e.stopImmediatePropagation();return;}if(a==='confirm-reopen'){demo.packageReady=false;demo.frameApproved=false;demo.delivery=false;demo.stale=demo.takeAccepted;}},true);


