const contract={gates:{},versions:{},reviews:{},viewed:'Shot preparation',intakePending:false,jobBinding:null,takeBinding:null,packageBinding:null,frameChecks:new Set(),backend:'ready',repairs:{},changes:[],proposal:null};
const requiredFrames=()=>shots.filter(s=>s.frameMode!=='references');
const busy=()=>state.running||demo.job==='running';
const statusOf=p=>contract.gates[p]||'upcoming';
const reviewed=p=>contract.reviews[p]===contract.versions[p];
const editable=p=>!busy()&&!contract.intakePending&&state.phase===p&&statusOf(p)==='draft';
const binding=()=>JSON.stringify({revision:state.revision,blockout:[spatial.source,spatial.file],cameras:setups.map(c=>[c.id,c.x,c.y,c.height]),shots:shots.map(s=>[s.id,s.duration,s.desc,s.camera,s.cast,s.frameMode||'start']),frames:[...contract.frameChecks].sort()});
const currentTakes=()=>demo.takes&&contract.takeBinding===binding()&&statusOf('Frames')==='approved';
function seedContract(){spatial.source='native';spatial.file='';spatial.refKind='Characters';spatial.view='layout';demo.entity='1';const index=phases().indexOf(state.phase);contract.gates=Object.fromEntries(phases().map((p,i)=>[p,i<index?'approved':i===index?'draft':'upcoming']));contract.versions=Object.fromEntries(phases().map(p=>[p,1]));contract.reviews={};contract.viewed=state.phase;contract.intakePending=demo.scenario==='New project';contract.jobBinding=null;contract.takeBinding=null;contract.packageBinding=null;contract.frameChecks=new Set(demo.frameApproved?requiredFrames().map(s=>s.id):[]);contract.backend='ready';contract.repairs={};contract.changes=[];contract.proposal=null;if(demo.packageReady)contract.packageBinding=binding();}
function invalidate(p){const preserveFrames=p==='Render'&&statusOf('Frames')==='approved',savedFrames=new Set(contract.frameChecks);const index=phases().indexOf(p);phases().slice(index).forEach((name,i)=>{contract.gates[name]=i===0?'draft':'upcoming';delete contract.reviews[name];});contract.versions[p]++;contract.frameChecks.clear();contract.packageBinding=null;contract.jobBinding=null;demo.packageReady=false;demo.frameApproved=false;demo.phaseReview=false;demo.phaseDraft=false;demo.delivery=false;demo.stale=demo.takes;demo.job='idle';demo.completed=0;demo.jobStep=0;state.phase=p;state.approved=statusOf('Shot preparation')==='approved';state.resolved=false;state.review='pending';if(preserveFrames){contract.frameChecks=savedFrames;demo.frameApproved=true;demo.packageReady=true;}}
function approvePhase(p){if(!editable(p)||!reviewed(p)||demo.phaseDraft)return;contract.gates[p]='approved';const next=phases()[phases().indexOf(p)+1];if(next){contract.gates[next]='draft';state.phase=next;contract.viewed=next;state.inspectPhase=next;}state.approved=statusOf('Shot preparation')==='approved';demo.phaseReview=false;demo.phaseDraft=false;state.work='plan';go(next==='Shot preparation'?'board':'phase');}
function reopenPhase(p){if(busy()||statusOf(p)!=='approved')return;invalidate(p);state.revision++;if(p==='Render'&&demo.frameApproved)contract.packageBinding=binding();contract.viewed=p;state.inspectPhase=p;demo.phaseDraft=!['Storyboard','References','Shot preparation','Frames'].includes(p);state.work='plan';log(p+' reopened · later approvals invalidated');go(p==='Shot preparation'||p==='Storyboard'?'board':'phase');}
function reviewedNow(){const p=state.phase;if(!editable(p)||demo.phaseDraft||contract.backend!=='ready')return;contract.reviews[p]=contract.versions[p];demo.phaseReview=true;log(p+' reviewed · revision '+contract.versions[p]);render();}
function routeChange(e){const t=e.target;if(!t.matches('[data-blockout-source],[data-blockout-file],[data-story-image]'))return;e.stopImmediatePropagation();if(t.disabled||!editable(contract.viewed))return;if(t.hasAttribute('data-blockout-source'))spatial.source=t.value;if(t.hasAttribute('data-blockout-file')){const file=t.files?.[0];spatial.file=file?(file.name.toLowerCase().endsWith('.mov')?file.name+' · unvalidated':'Choose a .mov file'):'';}if(t.hasAttribute('data-story-image'))shots[state.selected].useRendering=t.value==='render';invalidate(state.phase);state.revision++;render();}
function routeClick(e){const b=e.target.closest('button');if(!b)return;const a=b.dataset.action,x=b.dataset.x;if(['doc-edit','doc-reset'].includes(x)){e.stopImmediatePropagation();if(b.disabled||!editable(contract.viewed))return;demo.phaseDraft=x==='doc-edit';render();return;}const handled=b.dataset.phase||b.dataset.work||b.hasAttribute('data-shot')||b.dataset.refkind||b.dataset.reopenPhase||b.hasAttribute('data-entity')||b.hasAttribute('data-source-shot')||b.dataset.scenario||['board','list','animatic','blocking','production','save','check','hold','keep','approve','reopen','confirm-reopen','references','next','resume','current'].includes(a)||['return','source-shot','phase-check','doc-approve','sanity-approve','frames-approve','reopen-confirm','doc-save','intake-next','lyrics-save','job-start','job-confirm','take-accept','delivery','repair-save','creative','proposal-save','proposal-apply','proposal-cancel','decisions','backend-recover','open-generate','current-phase'].includes(x);if(!handled)return;e.stopImmediatePropagation();if(b.disabled)return;
if(b.dataset.scenario){setScenario(b.dataset.scenario);return;}
if(b.dataset.work){state.work=b.dataset.work;if(state.work==='plan'){contract.viewed=state.phase;state.inspectPhase=state.phase;}go('board');return;}
if(b.dataset.phase){contract.viewed=b.dataset.phase;state.inspectPhase=b.dataset.phase;state.work='plan';go(b.dataset.phase==='Shot preparation'||b.dataset.phase==='Storyboard'?'board':'phase');return;}
if(b.hasAttribute('data-shot')){state.selected=+b.dataset.shot;state.inspector=true;go(state.view==='production'?'production':'board');return;}
if(b.dataset.refkind){spatial.refKind=b.dataset.refkind;demo.entity=entityRows().find(r=>r.kind===spatial.refKind).id;render();return;}
if(b.hasAttribute('data-entity')){demo.entity=b.dataset.entity;render();return;}
if(b.hasAttribute('data-source-shot')){state.selected=+b.dataset.sourceShot;contract.viewed='Shot preparation';state.work='plan';go('board');return;}
if(['board','list','animatic','blocking','production'].includes(a)){if(!['Storyboard','Shot preparation'].includes(contract.viewed))contract.viewed='Shot preparation';go(a);return;}if(a==='references'){contract.viewed='References';state.inspectPhase='References';go('references');return;}
if(a==='current'){state.selected=(rows().find(s=>state.frame<s.end)||rows().at(-1)).index;go('board');return;}
if(a==='next'||a==='resume'||x==='current-phase'){contract.viewed=state.phase;state.inspectPhase=state.phase;state.work='plan';go(contract.intakePending?'intake':['Storyboard','Shot preparation'].includes(state.phase)?'board':'phase');return;}
if(b.dataset.reopenPhase||a==='reopen'){const p=b.dataset.reopenPhase||'Shot preparation';if(busy()||statusOf(p)!=='approved')return;demo.reopenTarget=p;go('phase-reopen');return;}
if(a==='confirm-reopen'||x==='reopen-confirm'){reopenPhase(demo.reopenTarget||'Shot preparation');return;}
if(x==='intake-next'||x==='lyrics-save'){if(!contract.intakePending)return;const music=state.pack==='Music Video';if(music&&demo.intake===0&&!demo.track)return;if(music&&demo.intake===3&&!demo.analysis)return;demo.intake++;demo.material=0;if(music&&demo.intake===3){contract.gates['Project Init']='approved';contract.gates['Audio Analysis']='draft';state.phase='Audio Analysis';}if(music&&demo.intake===4){contract.gates['Audio Analysis']='approved';state.phase='Brief';contract.gates.Brief='draft';}if(!music&&demo.intake===1){contract.gates['Project Init']='approved';state.phase='Brief';contract.gates.Brief='draft';}contract.viewed=state.phase;if(demo.intake>=(music?8:5)){contract.intakePending=false;state.inspectPhase='Brief';demo.phaseDraft=true;go('phase');}else go('intake');return;}
if(a==='save'){if(!editable(contract.viewed)||!['Storyboard','Shot preparation'].includes(contract.viewed))return;const n=Number($('#nf-duration').value);if(!Number.isFinite(n)||n<.5||n>30||n*2%1){$('.error').textContent='Use 0.5–30 seconds in 0.5-second steps.';return;}shots[state.selected].duration=n;changed();return;}
if(x==='doc-save'){if(!editable(contract.viewed))return;const value=$('[data-phase-text]').value.trim();if(!value){$('[data-phase-text]').setCustomValidity('Enter creative direction.');$('[data-phase-text]').reportValidity();return;}demo.phaseText[state.phase]=value;invalidate(state.phase);state.revision++;demo.phaseDraft=false;render();return;}
if(x==='phase-check'){if(contract.viewed===state.phase)reviewedNow();return;}
if(a==='check'){if(editable('Shot preparation')&&contract.backend==='ready')runReview();return;}
if(a==='hold'){if(!editable('Shot preparation'))return;shots[2].duration=Math.min(30,shots[2].duration+1);changed();return;}
if(a==='keep'){if(!editable('Shot preparation')||state.review!=='finding')return;contract.reviews['Shot preparation']=contract.versions['Shot preparation'];state.resolved=true;go('board');return;}
if(a==='approve'||x==='doc-approve'||x==='sanity-approve'){approvePhase(state.phase);return;}
if(x==='frames-approve'){if(!editable('Frames')||!requiredFrames().every(s=>contract.frameChecks.has(s.id)))return;contract.gates.Frames='approved';contract.gates.Render='draft';state.phase='Render';contract.viewed='Render';demo.frameApproved=true;demo.packageReady=true;contract.packageBinding=binding();state.work='generate';go('board');return;}
if(x==='return'||x==='source-shot'){state.work='plan';if(x==='source-shot')contract.viewed='Shot preparation';state.inspectPhase=contract.viewed;go(contract.intakePending?'intake':['Storyboard','Shot preparation'].includes(contract.viewed)?'board':contract.viewed==='References'?'references':'phase');return;}if(x==='open-generate'){state.work='generate';go('board');return;}
if(x==='job-confirm'){if(busy()||!demo.packageReady||contract.packageBinding!==binding())return;go('package');return;}
if(x==='job-start'){if(busy()||!demo.packageReady||contract.packageBinding!==binding()||!$('[data-spend-confirm]')?.checked)return;contract.jobBinding=binding();startJob();return;}
if(x==='take-accept'){if(!currentTakes()||demo.job!=='complete')return;contract.gates.Render='approved';demo.takeAccepted=true;demo.stale=false;state.work='edit';go('board');return;}
if(x==='delivery'){if(!demo.takeAccepted||!currentTakes())return;demo.delivery=true;log('Example delivery recorded · no file exported');render();return;}
if(x==='repair-save'){const field=$('[data-repair]'),text=field.value.trim();if(!text){field.setCustomValidity('Describe the correction.');field.reportValidity();return;}contract.repairs[shots[state.selected].id]={text,reason:$('[data-repair-reason]').value,shot:shots[state.selected].id,revision:state.revision};log('Repair saved on '+shots[state.selected].id+' · not submitted');state.work='generate';go('takes');return;}
if(x==='creative'){if(!editable(contract.viewed))return;go('creative');return;}
if(x==='proposal-save'){const text=$('[data-direction]').value.trim();if(!text){$('[data-direction]').setCustomValidity('Describe the intended change.');$('[data-direction]').reportValidity();return;}contract.proposal={shot:state.selected,phase:state.phase,version:contract.versions[state.phase],before:shots[state.selected].desc,text,field:$('[data-change-field]').value};go('proposal');return;}
if(x==='proposal-apply'){const p=contract.proposal;if(!p||!editable(p.phase)||p.version!==contract.versions[p.phase])return;shots[p.shot][p.field]=p.text;contract.changes.push({...p,id:shots[p.shot].id,result:'Applied'});contract.proposal=null;changed();return;}
if(x==='proposal-cancel'){if(contract.proposal)contract.changes.push({...contract.proposal,id:shots[contract.proposal.shot].id,result:'Declined'});contract.proposal=null;go('board');return;}
if(x==='decisions'){go('decisions');return;}
if(x==='backend-recover'){contract.backend='ready';log('Example backend available');render();}
}
