function sanityWorkspace(){const checks=[['Shot plan',shots.every(s=>s.duration>=.5&&s.duration<=30),'Every shot has a valid duration and identity.'],['Reference inputs',shots.every(s=>!!s.cast.trim()),'Named characters, objects and locations are linked.'],['Camera / blocking',setups.every(c=>Number.isFinite(c.height)&&c.height>0),'Camera setups have finite positions and positive height.'],['Source routes',shots.every(s=>['start','references'].includes(s.frameMode||'start')),'Each shot declares a frame or reference route.']];return heading('Sanity Check','Structural checks and creative advice remain separate')+'<div class="reading"><h2>Production readiness</h2>'+checks.map(([label,ok,detail])=>'<div class="check-row"><span class="'+(ok?'success':'error')+'">'+(ok?'✓':'!')+'</span><div><h3>'+label+'</h3><p class="small muted">'+(reviewed('Sanity Check')?detail:'Awaiting the current review run.')+'</p></div></div>').join('')+'<div class="advice"><h3>Creative review · 1D</h3><p>A hand close-up around the mechanism can drift. Consider showing one broad motion and cutting to the result.</p><div class="row">'+wb('finding','Inspect affected shot')+wb('advice','Keep this approach',!editable('Sanity Check')||workspace.acceptedAdvice)+'</div>'+(workspace.acceptedAdvice?'<p class="small">Director decision recorded · advice accepted as a known risk.</p>':'')+'</div>'+xb('phase-check','Run checks',!editable('Sanity Check')||reviewed('Sanity Check'),true)+xb('sanity-approve','Approve checks',!editable('Sanity Check')||!reviewed('Sanity Check'),true)+'</div>';}
